{
	int m_bits;
	unsigned m_value;
	const unsigned char *m_input;
};

extern unsigned g_rva01142be0[];

static int Rva009B46E0ReadBits(Rva009B46E0State *state, int count)
{
	unsigned value = state->m_value;
	int bits = state->m_bits;
	value &= g_rva01142be0[bits];
	int need = count - bits;
	unsigned result = 0;

	if (need > 0)
	{
		result = value << need;
		const unsigned char *input = state->m_input;
		value = input[0];
		value = (value << 8) + input[1];
		value = (value << 8) + input[2];
		value = (value << 8) + input[3];
		state->m_input = input + 4;
	}

	state->m_value = value;
	state->m_bits = 32 - need;
	return (value >> (32 - need)) | result;
}

// Absent-from-retail TU-local call used only to keep the internal-linkage
// register convention visible to MSVC; the claimed symbol is the reader above.
int Rva009B46E0ProbeCall(Rva009B46E0State *state, int count)
{
	return Rva009B46E0ReadBits(state, count);
}
